<div class="d-flex justify-content-between mb-4"><h1 class="h3">Canais</h1><a class="btn btn-primary" href="/canais/novo">Novo canal</a></div><div class="alert alert-info">OAuth e credenciais de redes sociais ainda não são solicitados nem armazenados.</div><div class="table-responsive"><table class="table table-bordered bg-white align-middle"><thead><tr><th>Nome</th><th>Plataforma</th><th>Identificador</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($channels as $channel): ?><tr><td><?= htmlspecialchars($channel['nome'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($channel['plataforma_nome'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($channel['identificador_externo'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= $channel['ativo'] ? 'Ativo' : 'Inativo' ?></td><td><a class="btn btn-sm btn-outline-primary" href="/canais/editar?id=<?= (int) $channel['id'] ?>">Editar</a></td></tr><?php endforeach; ?><?php if (!$channels): ?><tr><td colspan="5" class="text-center text-muted">Nenhum canal cadastrado.</td></tr><?php endif; ?></tbody></table></div><a href="/dashboard">Voltar ao dashboard</a>
